import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { readDocStructure, DocResourceLimitError, type DocStructure, type DocTable } from '../src/index.js';

// Fixtures are generated by test/fixtures/doc/generate-structure-fixtures.ps1 through Word COM;
// every expected value below is what that script sets.
const load = (name: string) => new Uint8Array(readFileSync(new URL(`./fixtures/doc/${name}`, import.meta.url)));
const read = (name: string): DocStructure => readDocStructure(load(name));
const trim = (s: string) => s.replace(/\r+$/, '');

describe('DOC tables', () => {
	it('reads a simple table with widths, header row, height, alignment, shading and borders', () => {
		const s = read('structure-table-simple.doc');
		expect(s.warnings).toEqual([]);
		expect(s.tables).toHaveLength(1);
		const t = s.tables[0]!;
		expect(t.story).toBe('main');
		expect(t.level).toBe(1);
		expect(t.rows).toHaveLength(3);
		expect(t.rows.map((r) => r.cells.map((c) => c.text))).toEqual([
			['R1C1', 'R1C2'],
			['R2C1', 'R2C2'],
			['R3C1', 'R3C2'],
		]);
		// Positions index the main story text: text before the table and after it stay outside.
		expect(s.main.text.slice(t.start, t.end)).toContain('R1C1');
		expect(s.main.text.slice(0, t.start)).toBe('Before table\r');
		expect(s.main.text.slice(t.end)).toBe('\rAfter table\r');
		const c = t.rows[0]!.cells[0]!;
		expect(s.main.text.slice(c.start, c.markCp)).toBe('R1C1');
		expect(s.main.text[c.markCp]).toBe('\x07');
		expect(s.main.text[t.rows[0]!.markCp]).toBe('\x07');
		expect(t.rows[0]!.cells.map((x) => x.props?.widthTwips)).toEqual([2000, 3000]);
		expect(t.rows[0]!.props?.gridTwips.length).toBe(3);
		expect(t.rows.map((r) => r.props?.alignment)).toEqual(['center', 'center', 'center']);
		expect(t.rows.map((r) => r.props?.isHeader)).toEqual([true, false, false]);
		expect(t.rows[1]!.props).toMatchObject({ heightRule: 'exact', heightTwips: 600 });
		expect(t.rows[2]!.props?.cantSplit).toBe(true);
		expect(t.rows[1]!.cells[0]!.props?.shading?.background).toBe('FF0000');
		expect(t.rows[2]!.cells[1]!.props?.verticalAlign).toBe('center');
		expect(t.rows[0]!.props?.borders.top).toMatchObject({ style: 'single', widthEighthPt: 4 });
		expect(t.rows[0]!.props?.borders.insideV?.style).toBe('single');
	});

	it('reads horizontal and vertical merges', () => {
		const t = read('structure-table-merged.doc').tables[0]!;
		expect(t.rows).toHaveLength(3);
		const [r1, r2, r3] = t.rows as [DocTable['rows'][0], DocTable['rows'][0], DocTable['rows'][0]];
		expect(r1.cells.map((c) => [c.gridColumn, c.columnSpan])).toEqual([[0, 2], [2, 1]]);
		expect(r1.cells[0]!.text).toContain('R1C1');
		expect(r1.cells[0]!.props?.widthTwips).toBe(6240);
		expect(r2.cells[2]).toMatchObject({ gridColumn: 2, rowSpan: 2 });
		expect(r2.cells[2]!.props?.vertMerge).toBe('restart');
		expect(r3.cells[2]!.props?.vertMerge).toBe('continue');
		expect(r3.cells.map((c) => c.gridColumn)).toEqual([0, 1, 2]);
	});

	it('nests a table inside a cell', () => {
		const s = read('structure-table-nested.doc');
		expect(s.tables).toHaveLength(1);
		const outer = s.tables[0]!;
		expect(outer.rows.map((r) => r.cells.length)).toEqual([2, 2]);
		const host = outer.rows[0]!.cells[1]!;
		expect(host.nestedTables).toHaveLength(1);
		const inner = host.nestedTables[0]!;
		expect(inner.level).toBe(2);
		expect(inner.rows.map((r) => r.cells.map((c) => c.text))).toEqual([
			['In11', 'In12'],
			['In21', 'In22'],
		]);
		expect(inner.start).toBeGreaterThanOrEqual(host.start);
		expect(inner.end).toBeLessThanOrEqual(host.end);
		expect(outer.rows[1]!.cells.map((c) => c.text)).toEqual(['Outer21', 'Outer22']);
		expect(outer.rows[0]!.cells[0]!.text).toBe('Outer11');
	});

	it('has no tables in documents without any', () => {
		expect(read('structure-notes.doc').tables).toEqual([]);
	});
});

describe('DOC sections', () => {
	const s = read('structure-sections.doc');
	it('decodes page setup, orientation, columns and break types', () => {
		expect(s.sections).toHaveLength(4);
		const [a, b, c, d] = s.sections as [DocStructure['sections'][0], DocStructure['sections'][0], DocStructure['sections'][0], DocStructure['sections'][0]];
		expect(a).toMatchObject({ orientation: 'portrait', pageWidthTwips: 12240, pageHeightTwips: 15840, marginLeftTwips: 1440, marginTopTwips: 1440, headerDistanceTwips: 720, footerDistanceTwips: 720, columnCount: 1 });
		expect(b).toMatchObject({
			orientation: 'landscape',
			pageWidthTwips: 15840,
			pageHeightTwips: 12240,
			marginLeftTwips: 1080,
			marginRightTwips: 1800,
			marginTopTwips: 1200,
			marginBottomTwips: 1320,
			gutterTwips: 360,
			headerDistanceTwips: 600,
			footerDistanceTwips: 800,
			columnCount: 2,
			columnSpacingTwips: 600,
			breakType: 'oddPage',
		});
		expect(c).toMatchObject({ breakType: 'nextPage', pageNumberFormat: 'lowerRoman', pageNumberStart: 5, pageNumberRestart: true, columnCount: 1 });
		expect(d.breakType).toBe('continuous');
	});
	it('covers the main story with consecutive CP ranges', () => {
		expect(s.sections.map((x) => s.main.text.slice(x.start, x.end).replace(/[\f\r]/g, ''))).toEqual(['Section one', 'Section two', 'Section three', 'Section four']);
		expect(s.sections[0]!.start).toBe(0);
		for (let i = 1; i < s.sections.length; i++) expect(s.sections[i]!.start).toBe(s.sections[i - 1]!.end);
	});
});

describe('DOC headers and footers', () => {
	const s = read('structure-headers.doc');
	const find = (section: number, kind: string, variant: string) => s.headersFooters.find((h) => h.section === section && h.kind === kind && h.variant === variant)!;
	it('maps every story to section, kind and variant', () => {
		expect(s.facingPages).toBe(true);
		expect(s.sections.map((x) => x.titlePage)).toEqual([true, false]);
		expect(s.headersFooters).toHaveLength(12);
		const text = (h: ReturnType<typeof find>) => trim(h.range.text);
		expect(text(find(0, 'header', 'default'))).toBe('Odd header 1');
		expect(text(find(0, 'header', 'even'))).toBe('Even header 1');
		expect(text(find(0, 'header', 'first'))).toBe('First header 1');
		expect(text(find(0, 'footer', 'default'))).toBe('Odd footer 1');
		expect(text(find(0, 'footer', 'even'))).toBe('Even footer 1');
		expect(text(find(0, 'footer', 'first'))).toBe('First footer 1');
		expect(find(0, 'header', 'default').range.story).toBe('headers');
	});
	it('inherits empty stories from the previous section', () => {
		const own = find(1, 'header', 'default');
		expect(own).toMatchObject({ inherited: false, sourceSection: 1 });
		expect(trim(own.range.text)).toBe('Odd header 2');
		const linked = find(1, 'footer', 'default');
		expect(linked).toMatchObject({ inherited: true, sourceSection: 0 });
		expect(linked.range.end).toBe(linked.range.start);
		expect(trim(linked.effective!.text)).toBe('Odd footer 1');
		expect(find(1, 'header', 'first').applies).toBe(false);
		expect(find(0, 'header', 'first').applies).toBe(true);
		expect(find(1, 'header', 'even').applies).toBe(true);
	});
	it('exposes the note separator stories', () => {
		expect(s.noteSeparators?.footnoteSeparator.text).toContain('\x03');
		expect(s.noteSeparators?.footnoteContinuationSeparator.text).toContain('\x04');
	});
});

describe('DOC footnotes, endnotes and comments', () => {
	const s = read('structure-notes.doc');
	it('reads footnotes and endnotes with reference positions', () => {
		expect(s.footnotes.map((n) => trim(n.range.text).replace('\x02 ', ''))).toEqual(['First footnote text', 'Second footnote text']);
		expect(s.endnotes.map((n) => trim(n.range.text).replace('\x02 ', ''))).toEqual(['First endnote text', 'Second endnote text']);
		for (const n of [...s.footnotes, ...s.endnotes]) {
			expect(n.autoNumbered).toBe(true);
			expect(s.main.text[n.refCp]).toBe('\x02');
		}
		expect(s.footnotes[0]!.range.story).toBe('footnotes');
		expect(s.endnotes[0]!.range.story).toBe('endnotes');
		expect(s.footnotes[1]!.range.start).toBe(s.footnotes[0]!.range.end);
	});
	it('reads comments with author, initials and date', () => {
		expect(s.comments.map((c) => [c.author, c.initials, trim(c.range.text).replace('\x05', '')])).toEqual([
			['Alice Author', 'AA', 'First comment text'],
			['Bob Builder', 'BB', 'Second comment text'],
		]);
		for (const c of s.comments) {
			expect(c.date).toMatch(/^20\d\d-\d\d-\d\dT\d\d:\d\d:00$/);
			expect(s.main.text[c.refCp]).toBe('\x05');
			expect(c.range.story).toBe('comments');
		}
	});
});

describe('DOC text boxes', () => {
	it('reads text box stories with their anchors', () => {
		const s = read('structure-textbox.doc');
		expect(s.textboxes.map((b) => trim(b.range.text))).toEqual(['Text box one', 'Text box two']);
		expect(s.textboxes.map((b) => b.story)).toEqual(['textboxes', 'textboxes']);
		for (const b of s.textboxes) {
			expect(s.main.text[b.anchorCp!]).toBe('\b');
			expect(b.shapeId).toBeGreaterThan(0);
		}
		expect(s.textboxes[0]!.rectTwips).toMatchObject({ right: 4560, bottom: 1560 });
		// 200 x 50 pt box.
		const r = s.textboxes[0]!.rectTwips!;
		expect([r.right - r.left, r.bottom - r.top]).toEqual([4000, 1000]);
	});
});

describe('DOC structure limits and hostile input', () => {
	it('throws DocResourceLimitError when a budget is exceeded', () => {
		const bytes = load('structure-table-simple.doc');
		expect(() => readDocStructure(bytes, { maxCharacters: 10 })).toThrow(DocResourceLimitError);
		expect(() => readDocStructure(bytes, { maxCells: 2 })).toThrow(DocResourceLimitError);
		expect(() => readDocStructure(bytes, { maxParagraphs: 3 })).toThrow(DocResourceLimitError);
		expect(() => readDocStructure(bytes, { maxSprms: 5 })).toThrow(DocResourceLimitError);
		expect(() => readDocStructure(bytes, { maxEntries: -1 })).toThrow();
	});
	it('rejects non-DOC input', () => {
		expect(() => readDocStructure(new Uint8Array(100))).toThrow();
		expect(() => readDocStructure(new Uint8Array(0))).toThrow();
	});
	it('never hangs or throws a non-Error on corrupted files', () => {
		const original = load('structure-table-nested.doc');
		let seed = 12345;
		const rand = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff);
		for (let run = 0; run < 150; run++) {
			const bytes = original.slice();
			for (let k = 0; k < 8; k++) bytes[rand() % bytes.length] = rand() & 0xff;
			try {
				readDocStructure(bytes, { maxCharacters: 100_000, maxParagraphs: 10_000, maxCells: 10_000, maxSprms: 100_000 });
			} catch (e) {
				expect(e).toBeInstanceOf(Error);
			}
		}
	});
});
